-- DUMMY SALES DATA for testing sales, order history and bills. Run in the Supabase SQL editor.
-- 36 orders over the last 10 days, from 12 fake customers (names start with "DUMMY", phones 90000000xx).
-- Every row has a note that starts with "DUMMY DATA", which is how the remove script finds them.
-- Items, GST (5% added on top for Frozen Nuggets, 5% already included for Zippy) and totals are worked out exactly
-- like a real order, so Print bill shows real-looking bills. Delivery charge is Rs 50 on every order.
-- Today's orders include new / confirmed / out-for-delivery ones, so the Live orders screen has something to show.
-- Note: orders take the next order numbers; after removing the dummy data those numbers are simply skipped.


-- A few customer ratings on delivered dummy orders (shows up in Feedback).
select id,
       (array[5, 4, 5, 3, 5, 2, 4])[1 + (rn % 7)::int],
       (array['Very fresh, delivered on time.', 'Good quality.', 'Loved the nuggets!', 'Delivery was a bit late.', 'Great packaging.', 'Order was missing an item.', 'Will order again.'])[1 + (rn % 7)::int]
from (
  select id, row_number() over (order by created_at) as rn
  from public.orders
  where note like 'DUMMY DATA%' and status = 'delivered'
) d
where rn % 3 = 0
on conflict (order_id) do nothing;
